/**
 * Live run of the AI answer review: one full TOEIC L&R exam generated by the
 * real providers on the disposable harness (scripts/qa/ai-exam-review-live-server.ts
 * on :3101, database nx_qa, Redis :6392). Generation only: nothing is
 * applied, so no Azure audio and no R2 upload.
 *
 * Writes the measured data to <out.json>; the report is written from it.
 * Usage: HARNESS_DB=nx_qa npx ts-node --transpile-only scripts/qa/ai-exam-review-live.ts <out.json>
 */
import { execFileSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import IORedis from 'ioredis';
import { call, newAdmin } from './harness-api';
import { harnessQuery } from './harness-db';
import { buildToeicListeningAudioScript } from '../../src/modules/toeic/toeic-listening-audio';
import { groupStimulus } from '../../src/modules/toeic/toeic-answer-review.logic';

const DAY = new Date().toISOString().slice(0, 10);
const SEED = 20261103;
const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

async function telemetry(redis: IORedis) {
  const keys = await redis.keys('gemini:telemetry:*');
  const values = keys.length ? await redis.mget(keys) : [];
  return {
    review: await redis.hgetall(`ai:answer-review:telemetry:${DAY}`),
    gemini: Object.fromEntries(keys.map((key, i) => [key, Number(values[i] ?? 0)])),
    dailyQuota: Number((await redis.get(`gemini:daily_quota:${DAY}`)) ?? 0),
  };
}

function delta(before: Record<string, any>, after: Record<string, any>) {
  const out: Record<string, number> = {};
  for (const key of new Set([...Object.keys(before), ...Object.keys(after)])) {
    const value = Number(after[key] ?? 0) - Number(before[key] ?? 0);
    if (value) out[key] = value;
  }
  return out;
}

/** The job's draftSnapshot, read straight from harness-pg with a big buffer. */
function snapshotOf(jobId: string) {
  // harnessQuery refuses a protected cluster before any read.
  harnessQuery('select 1');
  const out = execFileSync(
    'docker',
    [
      'exec',
      'harness-pg',
      'psql',
      '-U',
      'harness',
      '-d',
      process.env.HARNESS_DB ?? 'nx_qa',
      '-tA',
      '-c',
      `select "draftSnapshot"::text from "AiGenerationJob" where id = '${jobId}'`,
    ],
    { encoding: 'utf8', maxBuffer: 256 * 1024 * 1024 },
  );
  return JSON.parse(out.trim());
}

function mulberry32(seed: number) {
  return () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** 15 agreed items: at least 2 per Part when it has 2, the rest by share. */
function stratified<T extends { part: number }>(items: T[], total = 15) {
  const random = mulberry32(SEED);
  const byPart = new Map<number, T[]>();
  for (const item of items)
    byPart.set(item.part, [...(byPart.get(item.part) ?? []), item]);
  const parts = [...byPart.keys()].sort((a, b) => a - b);
  const quota = new Map(parts.map((part) => [part, Math.min(2, byPart.get(part)!.length)]));
  let left = total - [...quota.values()].reduce((a, b) => a + b, 0);
  const shares = parts
    .map((part) => ({
      part,
      share: (byPart.get(part)!.length / items.length) * left,
    }))
    .sort((a, b) => (b.share % 1) - (a.share % 1));
  for (const { part, share } of shares) {
    const extra = Math.min(Math.floor(share), byPart.get(part)!.length - quota.get(part)!);
    quota.set(part, quota.get(part)! + extra);
  }
  left = total - [...quota.values()].reduce((a, b) => a + b, 0);
  for (const { part } of shares) {
    if (left <= 0) break;
    if (quota.get(part)! < byPart.get(part)!.length) {
      quota.set(part, quota.get(part)! + 1);
      left -= 1;
    }
  }
  const picked: T[] = [];
  for (const part of parts) {
    const pool = [...byPart.get(part)!];
    for (let i = pool.length - 1; i > 0; i -= 1) {
      const j = Math.floor(random() * (i + 1));
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    picked.push(...pool.slice(0, quota.get(part)));
  }
  return { picked, quota: Object.fromEntries(quota) };
}

async function main() {
  const out = process.argv[2];
  const redis = new IORedis('redis://127.0.0.1:6392');
  const before = await telemetry(redis);
  const admin = await newAdmin('live-review');
  const startedAt = Date.now();
  const started = await call('POST', '/admin/exams/ai/generate', admin.token, {
    familyCode: 'TOEIC',
    variantCode: 'TOEIC_LR',
    mode: 'FULL_EXAM',
    difficulty: 'medium',
  });
  const jobId: string = started.data?.id;
  if (!jobId) throw new Error(`generate refused: ${JSON.stringify(started)}`);
  console.log(`job ${jobId}`);

  const failures: Array<{ at: string; error: string }> = [];
  let status: any;
  let lastStage = '';
  for (let tick = 0; tick < 12 * 150; tick += 1) {
    status = (await call('GET', `/admin/exams/ai/jobs/${jobId}`, admin.token)).data;
    const parts = Object.entries(status?.progress ?? {})
      .map(([part, p]: any) => `P${part}:${p.completedGroups ?? '?'}/${p.totalGroups ?? '?'}`)
      .join(' ');
    const stage = `${status?.status} ${status?.stage} ${parts}`;
    if (stage !== lastStage) console.log(`progress ${stage}`);
    lastStage = stage;
    if (status?.status === 'GENERATED') break;
    if (status?.status === 'FAILED') {
      failures.push({ at: new Date().toISOString(), error: String(status.error ?? '') });
      console.log(`failed ${String(status.error ?? '').slice(0, 200)}`);
      if (failures.length > 4) break;
      await sleep(60_000);
      await call('POST', `/admin/exams/ai/jobs/${jobId}/retry`, admin.token);
    }
    await sleep(5_000);
  }
  const elapsedSeconds = Math.round((Date.now() - startedAt) / 1000);
  const after = await telemetry(redis);
  await redis.quit();
  const snapshot = snapshotOf(jobId);

  // ---- measure ------------------------------------------------------------
  const verdictAllDrafts: Record<string, number> = {};
  const add = (counts: Record<string, number>) => {
    for (const [key, value] of Object.entries(counts))
      verdictAllDrafts[key] = (verdictAllDrafts[key] ?? 0) + value;
  };
  const explanationCauses: Record<string, number> = {};
  const refusedItems: any[] = [];
  const agreed: any[] = [];
  const statusByPart: Record<string, Record<string, number>> = {};
  const regeneration = {
    batches: 0,
    batchesRedrafted: 0,
    redraftsForContent: 0,
    redraftsForReview: 0,
    acceptedAfterRedraft: 0,
    finalRefusedBatches: 0,
  };
  const stepStatus: Record<string, Record<string, number>> = {};
  const providers: Record<string, number> = {};
  const asset = {
    part1WithBrief: 0,
    part1Groups: 0,
    listeningScriptsOk: 0,
    listeningGroups: 0,
    stimulusPresent: 0,
    stimulusGroups: 0,
    questions: 0,
    questionsByPart: {} as Record<string, number>,
  };

  for (const batch of snapshot.lrBatches ?? []) {
    const part = Number(batch.part);
    regeneration.batches += 1;
    const drafts: any[] = batch.drafts ?? [];
    if (drafts.length > 1) regeneration.batchesRedrafted += 1;
    for (const draft of drafts) {
      if (draft.outcome === 'CONTENT_CONTRACT') regeneration.redraftsForContent += 1;
      if (draft.outcome === 'REVIEW_REJECTED') {
        regeneration.redraftsForReview += 1;
        add(draft.verdictCounts ?? {});
        for (const item of draft.refused ?? []) {
          refusedItems.push({ part, batchKey: batch.batchKey, attempt: draft.attempt, ...item });
          for (const cause of item.explanation?.causes ?? [])
            explanationCauses[cause] = (explanationCauses[cause] ?? 0) + 1;
        }
      }
    }
    const last = drafts[drafts.length - 1];
    if (last?.outcome === 'ACCEPTED' && drafts.length > 1) regeneration.acceptedAfterRedraft += 1;
    if (last?.outcome === 'REVIEW_REJECTED') regeneration.finalRefusedBatches += 1;

    let questionNumber = Number(batch.questionNumber);
    for (const group of batch.candidate?.groups ?? []) {
      const status = part === 1 ? 'PART1_DRAFT_GATE' : (group.review?.status ?? 'UNREVIEWED');
      statusByPart[part] = statusByPart[part] ?? {};
      statusByPart[part][status] = (statusByPart[part][status] ?? 0) + 1;
      if (group.provider) providers[group.provider] = (providers[group.provider] ?? 0) + 1;
      for (const [name, step] of Object.entries(group.review?.steps ?? {}) as any) {
        const key = `${name}:${step.provider ?? 'none'}:${step.reviewKind}:${step.status}`;
        stepStatus[name] = stepStatus[name] ?? {};
        stepStatus[name][key] = (stepStatus[name][key] ?? 0) + 1;
      }
      if (last?.outcome === 'ACCEPTED' && part !== 1)
        add(
          (group.review?.verdicts ?? []).reduce((acc: Record<string, number>, row: any) => {
            acc[row.verdict] = (acc[row.verdict] ?? 0) + 1;
            return acc;
          }, {}),
        );
      if (part === 1) {
        asset.part1Groups += 1;
        if (String(group.imageBrief ?? '').trim()) asset.part1WithBrief += 1;
      }
      if (part <= 4) {
        asset.listeningGroups += 1;
        try {
          buildToeicListeningAudioScript({
            part,
            transcriptText: group.transcript,
            passageText: group.passageText,
            questions: group.questions,
          });
          asset.listeningScriptsOk += 1;
        } catch {
          // counted as not buildable
        }
      }
      if (part >= 2 && part !== 5) {
        asset.stimulusGroups += 1;
        if (groupStimulus(part, group)) asset.stimulusPresent += 1;
      }
      for (const [index, question] of (group.questions ?? []).entries()) {
        asset.questions += 1;
        asset.questionsByPart[part] = (asset.questionsByPart[part] ?? 0) + 1;
        const row = (group.review?.verdicts ?? []).find(
          (v: any) => v.questionNumber === questionNumber + index,
        );
        if (part !== 1 && row?.verdict === 'AGREE')
          agreed.push({
            part,
            questionNumber: questionNumber + index,
            stimulus: groupStimulus(part, group)?.slice(0, 2500) ?? null,
            question,
            solve: row.solve,
            explanation: row.explanation,
          });
      }
      questionNumber += group.questions?.length ?? 0;
    }
  }
  const sample = stratified(agreed);

  const result = {
    jobId,
    elapsedSeconds,
    finalStatus: status?.status,
    failures,
    failedUnits: (snapshot.failedUnits ?? []).map((unit: any) => ({
      batchKey: unit.batchKey,
      code: unit.code,
      attempts: unit.attempts,
      message: String(unit.message).slice(0, 300),
    })),
    statusByPart,
    stepStatus,
    generatorProviders: providers,
    verdictAllDrafts,
    explanationCauses,
    regeneration,
    asset,
    telemetry: {
      review: delta(before.review, after.review),
      gemini: delta(before.gemini, after.gemini),
      dailyQuota: after.dailyQuota - before.dailyQuota,
    },
    triage: {
      seed: SEED,
      sampleQuota: sample.quota,
      agreedPool: agreed.length,
      refused: refusedItems,
      agreedSample: sample.picked,
    },
  };
  writeFileSync(out, JSON.stringify(result, null, 2));
  console.log(
    `done ${result.finalStatus} in ${elapsedSeconds}s, refused items ${refusedItems.length}, sample ${sample.picked.length}`,
  );
}

main().catch((error) => {
  console.error(`live run error: ${String(error?.message ?? error)}`);
  process.exit(1);
});
